// Converte blocos do Notion em Markdown
const pageData = $('Ler conteúdo da página').first().json;
const blocks  = $input.all().map(i => i.json);

function richTextToMd(richTexts = []) {
  return richTexts.map(t => {
    let text = t.plain_text || '';
    if (t.annotations?.code)          text = `\`${text}\``;
    if (t.annotations?.bold)          text = `**${text}**`;
    if (t.annotations?.italic)        text = `_${text}_`;
    if (t.annotations?.strikethrough) text = `~~${text}~~`;
    if (t.href)                        text = `[${text}](${t.href})`;
    return text;
  }).join('');
}

function blockToMd(block, depth = 0) {
  const indent = '  '.repeat(depth);
  const t = block.type;
  const d = block[t] || {};

  switch (t) {
    case 'heading_1':       return `# ${richTextToMd(d.rich_text)}`;
    case 'heading_2':       return `## ${richTextToMd(d.rich_text)}`;
    case 'heading_3':       return `### ${richTextToMd(d.rich_text)}`;
    case 'paragraph':       return richTextToMd(d.rich_text) || '';
    case 'bulleted_list_item': return `${indent}- ${richTextToMd(d.rich_text)}`;
    case 'numbered_list_item': return `${indent}1. ${richTextToMd(d.rich_text)}`;
    case 'to_do':           return `${indent}- [${d.checked ? 'x' : ' '}] ${richTextToMd(d.rich_text)}`;
    case 'toggle':          return `${indent}> ${richTextToMd(d.rich_text)}`;
    case 'quote':           return `> ${richTextToMd(d.rich_text)}`;
    case 'callout':         return `> [!NOTE]\n> ${richTextToMd(d.rich_text)}`;
    case 'code':            return `\`\`\`${d.language || ''}\n${richTextToMd(d.rich_text)}\n\`\`\``;
    case 'divider':         return '---';
    case 'image': {
      const url = d.type === 'external' ? d.external?.url : d.file?.url;
      return `![image](${url})`;
    }
    case 'bookmark':        return `[${d.url}](${d.url})`;
    default:                return '';
  }
}

const title = pageData.properties?.Name?.title?.[0]?.plain_text
           || pageData.properties?.title?.title?.[0]?.plain_text
           || 'Sem título';
const notionUrl = `https://notion.so/${pageData.id.replace(/-/g, '')}`;
const lastEdited = pageData.last_edited_time;

const frontmatter = [
  '---',
  `notion_id: "${pageData.id}"`,
  `notion_url: "${notionUrl}"`,
  `last_synced: "${new Date().toISOString()}"`,
  `last_edited: "${lastEdited}"`,
  '---',
].join('\n');

const body = blocks.map(b => blockToMd(b)).filter(Boolean).join('\n\n');
const markdown = `${frontmatter}\n\n# ${title}\n\n${body}`;

const safeTitle = title.replace(/[/\\?%*:|"<>]/g, '-');
const folder = $env.OBSIDIAN_VAULT_FOLDER || 'Notion Sync';
const filePath = `${folder}/${safeTitle}.md`;

return [{ json: { pageId: pageData.id, title, filePath, markdown, lastEdited } }];

// Atualiza o timestamp do último sync bem-sucedido
$workflow.staticData.lastSyncAt = new Date().toISOString();
return $input.all();

const count = $input.all().length;
console.log(`[notion→obsidian] nenhuma página nova. Último sync: ${$workflow.staticData.lastSyncAt}`);
return [{ json: { synced: 0, message: 'Nenhuma página alterada desde o último sync.' } }];
